effect.shader:
const float PI = 3.14159265;

float hash(vec2 p) {
    // Primos grandes e um seno: o gerador de ruído mais usado em shader. O que
    // importa dele é embaralhar bem pixels vizinhos, e isso ele faz.
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

/** Ruído de valor com interpolação suave — a base de tudo aqui. */
float ruido(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 s = f * f * (3.0 - 2.0 * f);

    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    return mix(mix(a, b, s.x), mix(c, d, s.x), s.y);
}

/**
 * Ruído somado em camadas.
 *
 * Cada camada anda numa velocidade própria (`float(i) * 0.37`), e é isso que
 * faz a nuvem se DEFORMAR enquanto anda em vez de deslizar inteira.
 */
float nuvem(vec2 p, vec2 vento, int quantas) {
    float soma = 0.0;
    float peso = 0.0;
    float amplitude = 1.0;
    float frequencia = 1.0;

    for (int i = 0; i < 7; i++) {
        if (i >= quantas) break;
        vec2 deslocada = p * frequencia + vento * (1.0 + float(i) * 0.37 * drift);
        soma += ruido(deslocada) * amplitude;
        peso += amplitude;
        amplitude *= 0.5;
        frequencia *= 2.0;
    }

    return soma / max(peso, 1e-4);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 p = vec2(acScreenNorm.x * acAspect, acScreenNorm.y) * scale;
    float anguloVento = windAngle * PI / 180.0;
    vec2 vento = vec2(cos(anguloVento), sin(anguloVento)) * acTime * speed;

    int quantas = clamp(int(layers + 0.5), 1, 7);
    float n = nuvem(p, vento, quantas);

    // A cobertura é um CORTE, não um multiplicador: céu é ruído cortado, e é o
    // corte que separa "algumas nuvens" de "encoberto".
    float corte = 1.0 - coverage;
    float densidade = smoothstep(corte, corte + softness, n);

    // O volume sai do gradiente do próprio ruído: onde ele cresce na direção da
    // luz, a nuvem clareia. É o mesmo princípio do relevo, e é o que impede a
    // nuvem de parecer uma mancha chapada.
    float passo = 0.02 * scale;
    float dx = nuvem(p + vec2(passo, 0.0), vento, quantas) - n;
    float dy = nuvem(p + vec2(0.0, passo), vento, quantas) - n;

    float anguloLuz = lightAngle * PI / 180.0;
    vec2 luz = vec2(cos(anguloLuz), -sin(anguloLuz));
    float claro = dot(normalize(vec2(dx, dy) + 1e-5), luz) * relief;

    vec3 cor = clamp(cloudColor.rgb * (1.0 + claro), 0.0, 2.0);
    float alfa = densidade * cloudColor.a;

    // O fundo é opcional: com alfa zero nele, a nuvem sai sobre o que já estava,
    // que é o caso de fumaça por cima de um vídeo.
    vec3 comFundo = mix(skyColor.rgb, cor, alfa);
    float alfaFinal = max(alfa, skyColor.a);

    vec4 desenhado = vec4(comFundo, alfaFinal);
    float saidaAlfa = desenhado.a + original.a * (1.0 - desenhado.a);
    vec3 saidaCor = saidaAlfa > 0.0
        ? (desenhado.rgb * desenhado.a + original.rgb * original.a * (1.0 - desenhado.a)) / saidaAlfa
        : vec3(0.0);

    fragColor = vec4(saidaCor, saidaAlfa);
}
